    "text": "57 | export const bodyLimit = (options: BodyLimitOptions): MiddlewareHandler => {
58 |   const onError: OnError =
59 |     options.onError ||
60 |     (() => {
61 |       const res = new Response(ERROR_MESSAGE, {
62 |         status: 413,
63 |       })
64 |       throw new HTTPException(413, { res })
65 |     })
66 |   const maxSize = options.maxSize
67 | 
68 |   return async function bodyLimit(c, next) {
69 |     if (!c.req.raw.body) {
70 |       // maybe GET or HEAD request
71 |       return next()
72 |     }
73 | 
74 |     const hasTransferEncoding = c.req.raw.headers.has('transfer-encoding')
75 |     const hasContentLength = c.req.raw.headers.has('content-length')
76 | 
77 |     // RFC 7230: If both Transfer-Encoding and Content-Length are present,
78 |     // Transfer-Encoding takes precedence and Content-Length should be ignored
79 |     if (hasTransferEncoding && hasContentLength) {
80 |       // Both headers present - follow RFC 7230 and ignore Content-Length
81 |       // This might indicate request smuggling attempt
82 |     }
83 | 
84 |     if (hasContentLength && !hasTransferEncoding) {
85 |       // Only Content-Length present - we can trust it
86 |       const contentLength = parseInt(c.req.raw.headers.get('content-length') || '0', 10)
87 |       return contentLength > maxSize ? onError(c) : next()
88 |     }
89 | 
90 |     // Transfer-Encoding present (chunked) or no length headers
91 | 
92 |     let size = 0
93 |     const rawReader = c.req.raw.body.getReader()
94 |     const reader = new ReadableStream({
95 |       async start(controller) {
96 |         try {
97 |           for (;;) {
98 |             const { done, value } = await rawReader.read()
99 |             if (done) {
100 |               break
101 |             }
102 |             size += value.length
103 |             if (size > maxSize) {
104 |               controller.error(new BodyLimitError(ERROR_MESSAGE))
105 |               break
106 |             }
107 | 
108 |             controller.enqueue(value)
109 |           }
110 |         } finally {
111 |           controller.close()
112 |         }
113 |       },
114 |     })
115 | 
116 |     const requestInit: RequestInit & { duplex: 'half' } = { body: reader, duplex: 'half' }
117 |     c.req.raw = new Request(c.req.raw, requestInit as RequestInit)
118 | 
119 |     await next()
120 | 
121 |     if (c.error instanceof BodyLimitError) {
122 |       c.res = await onError(c)
123 |     }
124 |   }
125 | }"
